// === SACAR LOADERS "guidde" DE kb_guidde_s3 ===
const allInput = $input.all();  // <- CAMBIO CLAVE: Todos los items

// Normalizar stores desde todos los items
let stores = [];
for (const item of allInput) {
  const data = item.json;
  if (Array.isArray(data)) {
    stores = stores.concat(data);
  } else {
    stores.push(data);
  }
}

// Resto igual...
const targetStoreName = 'kb_guidde_s3';
const guiddeStore = stores.find(s => (s.name || '').toLowerCase().trim() === targetStoreName.toLowerCase().trim());

if (!guiddeStore) {
  return [{
    json: { 
      ok: false, 
      error: `No se encontró "${targetStoreName}"`,
      availableStores: stores.map(s => s.name).filter(Boolean),
      totalStoresFound: stores.length,
      inputItemsCount: allInput.length
    }
  }];
}

// Filtrar loaders "guidde" (igual que antes)
const needle = 'guidde';
const loaders = Array.isArray(guiddeStore.loaders) ? guiddeStore.loaders : [];
const guiddeLoaders = loaders.filter(l => 
  String(l.loaderName || '').toLowerCase().trim().includes(needle)
);

if (guiddeLoaders.length === 0) {
  return [{ json: { ok: false, storeId: guiddeStore.id, storeName: guiddeStore.name, error: `No loaders "${needle}"` } }];
}

return guiddeLoaders.map(l => ({
  json: {
    ok: true,
    storeId: guiddeStore.id,
    storeName: guiddeStore.name,
    docId: l.id,
    loaderName: l.loaderName,
    prefix: l.loaderConfig?.prefix,
    bucketName: l.loaderConfig?.bucketName,
    status: l.status,
    totalChunks: l.totalChunks,
    totalChars: l.totalChars
  }
}));

// Config_Upsert CORREGIDO
const STORE_ID = 'ddbcfeaa-7c71-4220-90d4-f2d09eed642f'; // kb_guidde_s3
const API_HOST = 'https://mobilvendor-ai.com';

return $input.all().map(({ json }) => {
  const metadataObj = {
    loaderName: json.loaderName,
    prefix: json.prefix,
    bucketName: json.bucketName,
    source: 'Guidde-S3',
    updatedAt: new Date().toISOString(),
  };

  // Usa el credential del loader original, si existe
  const credentialId = json.credential || '8e97fc05-3f3a-4e12-8f4d-3f8b27b4f7b1';

  return {
    json: {
      ...json,
      flowiseUrl: `${API_HOST}/api/v1/document-store/upsert/${STORE_ID}`,
      payload: {
        docId: json.docId,          // loader.id
        loaderName: json.loaderName,
        replaceExisting: true,
        metadata: metadataObj,
        loader: {
          id: 's3Directory',        // tipo de loader
          config: {
            bucketName: json.bucketName,
            prefix: json.prefix,
            region: 'us-east-1',
            FLOWISE_CREDENTIAL_ID: credentialId,   // ← CLAVE
            pdfUsage: 'perFile'
          }
        },
        splitter: {
          config: {
            encodingName: 'gpt2',
            chunkSize: 7500,
            chunkOverlap: 250
          }
        }
      }
    }
  };
});
